		Value inherited = SimpleValueFactory.getInstance().createLiteral("inherited-".repeat(8192));
		Value payload = SimpleValueFactory.getInstance().createLiteral("right");
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(source.idSpace()).thenReturn(source);
